import React, { useState } from 'react';
import DashboardLayout from './DashboardLayout';
import { Upload, Video, Check, AlertCircle, FileVideo, Building, Camera as CameraIcon } from 'lucide-react';

const UploadVideoPage = ({ user, branches, cameras, onUploadVideo, onNavigate, onLogout }) => {
  const [selectedFile, setSelectedFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [uploadSuccess, setUploadSuccess] = useState(false);
  const [error, setError] = useState('');
  const [metadata, setMetadata] = useState({ branch_id: '', camera_id: '', description: '' });

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    setError('');
    setUploadSuccess(false);

    if (file) {
      if (!file.type.startsWith('video/')) {
        setError('Please select a valid video file');
        return;
      }

      const maxSize = 500 * 1024 * 1024;
      if (file.size > maxSize) {
        setError('File size exceeds 500MB limit');
        return;
      }

      setSelectedFile(file);
    }
  };

  const handleUpload = async () => {
    if (!selectedFile) {
      setError('Please select a video file');
      return;
    }

    setError('');
    setUploading(true);
    setUploadProgress(0);

    const progressInterval = setInterval(() => {
      setUploadProgress((prev) => {
        if (prev >= 90) {
          clearInterval(progressInterval);
          return 90;
        }
        return prev + 10;
      });
    }, 200);

    const result = await onUploadVideo({
      filename: selectedFile.name,
      filepath: `/uploads/${selectedFile.name}`,
      camera_id: metadata.camera_id || null,
      branch_id: metadata.branch_id || null,
      description: metadata.description
    });

    clearInterval(progressInterval);
    setUploadProgress(100);

    setTimeout(() => {
      setUploading(false);

      if (result.success) {
        setUploadSuccess(true);
        setTimeout(() => {
          setSelectedFile(null);
          setUploadSuccess(false);
          setUploadProgress(0);
          setMetadata({ branch_id: '', camera_id: '', description: '' });
        }, 2000);
      } else {
        setError(result.error || 'Upload failed. Please try again.');
      }
    }, 500);
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];
  };

  const filteredCameras = metadata.branch_id 
    ? cameras.filter(c => c.branch_id === parseInt(metadata.branch_id))
    : cameras;

  return (
    <DashboardLayout user={user} currentPage="videos" onNavigate={onNavigate} onLogout={onLogout}>
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900">Upload Video</h1>
        <p className="text-gray-600 mt-2">Upload videos for AI-powered analysis</p>
      </div>

      <div className="grid lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2">
          <div className="bg-white rounded-xl shadow-sm p-8">
            {error && (
              <div className="bg-red-50 border border-red-200 text-red-600 p-4 rounded-lg mb-6 flex items-start">
                <AlertCircle className="w-5 h-5 mr-2 flex-shrink-0 mt-0.5" />
                <span>{error}</span>
              </div>
            )}

            {uploadSuccess && (
              <div className="bg-green-50 border border-green-200 text-green-600 p-4 rounded-lg mb-6 flex items-start">
                <Check className="w-5 h-5 mr-2 flex-shrink-0 mt-0.5" />
                <span>Video uploaded successfully!</span>
              </div>
            )}

            <div className="border-2 border-dashed border-gray-300 rounded-xl p-12 text-center hover:border-blue-400 transition-colors">
              <div className="max-w-md mx-auto">
                <div className="w-20 h-20 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4">
                  <Upload className="w-10 h-10 text-blue-600" />
                </div>
                <h3 className="text-lg font-semibold text-gray-900 mb-2">Upload Video for Analysis</h3>
                <p className="text-gray-600 mb-6 text-sm">Drag and drop your video file here, or click to browse</p>
                
                <input
                  type="file"
                  accept="video/*"
                  onChange={handleFileChange}
                  className="hidden"
                  id="video-upload"
                  disabled={uploading}
                />
                <label
                  htmlFor="video-upload"
                  className={`inline-block px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 cursor-pointer font-medium shadow-md hover:shadow-lg transition-all ${
                    uploading ? 'opacity-50 cursor-not-allowed' : ''
                  }`}
                >
                  Choose Video File
                </label>

                <p className="text-xs text-gray-500 mt-4">Supported formats: MP4, AVI, MOV, MKV • Max size: 500MB</p>
              </div>
            </div>

            {selectedFile && (
              <div className="mt-6 animate-fadeIn">
                <div className="bg-gray-50 rounded-lg p-4 border border-gray-200">
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex items-start space-x-3">
                      <div className="w-10 h-10 bg-purple-100 rounded-lg flex items-center justify-center flex-shrink-0">
                        <FileVideo className="w-6 h-6 text-purple-600" />
                      </div>
                      <div>
                        <p className="font-semibold text-gray-900">{selectedFile.name}</p>
                        <p className="text-sm text-gray-600">{formatFileSize(selectedFile.size)}</p>
                      </div>
                    </div>
                    {!uploading && (
                      <button
                        onClick={() => {
                          setSelectedFile(null);
                          setUploadProgress(0);
                          setError('');
                        }}
                        className="text-red-600 hover:text-red-800 text-sm font-medium"
                      >
                        Remove
                      </button>
                    )}
                  </div>

                  {uploading && (
                    <div className="mb-4">
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-sm font-medium text-gray-700">Uploading...</span>
                        <span className="text-sm font-medium text-blue-600">{uploadProgress}%</span>
                      </div>
                      <div className="w-full bg-gray-200 rounded-full h-2">
                        <div
                          className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                          style={{ width: `${uploadProgress}%` }}
                        ></div>
                      </div>
                    </div>
                  )}

                  <div className="space-y-3 mb-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Select Branch (Optional)</label>
                      <select
                        value={metadata.branch_id}
                        onChange={(e) => setMetadata({ ...metadata, branch_id: e.target.value, camera_id: '' })}
                        disabled={uploading}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                      >
                        <option value="">No specific branch</option>
                        {branches.map((branch) => (
                          <option key={branch.id} value={branch.id}>{branch.name}</option>
                        ))}
                      </select>
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Select Camera (Optional)</label>
                      <select
                        value={metadata.camera_id}
                        onChange={(e) => setMetadata({ ...metadata, camera_id: e.target.value })}
                        disabled={uploading || !metadata.branch_id}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                      >
                        <option value="">No specific camera</option>
                        {filteredCameras.map((camera) => (
                          <option key={camera.id} value={camera.id}>{camera.name}</option>
                        ))}
                      </select>
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Description (Optional)</label>
                      <textarea
                        value={metadata.description}
                        onChange={(e) => setMetadata({ ...metadata, description: e.target.value })}
                        disabled={uploading}
                        rows={2}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                        placeholder="Add notes about this video..."
                      />
                    </div>
                  </div>

                  <button
                    onClick={handleUpload}
                    disabled={uploading}
                    className="w-full bg-green-600 text-white py-3 rounded-lg hover:bg-green-700 font-medium shadow-md hover:shadow-lg transition-all disabled:bg-gray-400 disabled:cursor-not-allowed flex items-center justify-center space-x-2"
                  >
                    {uploading ? (
                      <>
                        <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        <span>Uploading...</span>
                      </>
                    ) : (
                      <>
                        <Upload className="w-5 h-5" />
                        <span>Upload & Analyze</span>
                      </>
                    )}
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-blue-50 rounded-xl p-6 border border-blue-200">
            <h3 className="font-semibold text-blue-900 mb-3 flex items-center">
              <Video className="w-5 h-5 mr-2" />
              How it works
            </h3>
            <ul className="space-y-2 text-sm text-blue-800">
              <li className="flex items-start">
                <span className="mr-2">1.</span>
                <span>Upload your video file</span>
              </li>
              <li className="flex items-start">
                <span className="mr-2">2.</span>
                <span>AI analyzes the content</span>
              </li>
              <li className="flex items-start">
                <span className="mr-2">3.</span>
                <span>Receive detailed insights</span>
              </li>
              <li className="flex items-start">
                <span className="mr-2">4.</span>
                <span>View results in reports</span>
              </li>
            </ul>
          </div>

          <div className="bg-white rounded-xl shadow-sm p-6">
            <h3 className="font-semibold text-gray-900 mb-4">Your Statistics</h3>
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-600">Videos Uploaded</span>
                <span className="font-semibold text-gray-900">0</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-600">Total Size</span>
                <span className="font-semibold text-gray-900">0 MB</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-600">Analyzed</span>
                <span className="font-semibold text-green-600">0</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </DashboardLayout>
  );
};

export default UploadVideoPage;
